IntervalIterator expandMultiTermIntervals(
    CompiledAutomaton automaton,
    int maxExpansions,
    String pattern,
    String field,
    LeafReaderContext ctx)
    throws IOException {
  this.termOps++;
  this.termField = field;
  Terms terms = termsForField(ctx);
  if (terms == null) {
    return null;
  }
  List<IntervalIterator> subSources = new ArrayList<>();
  this.termEnum = automaton.getTermsEnum(terms);
  BytesRef term;
  int count = 0;
  while ((term = this.termEnum.next()) != null) {
    this.termPostingBytes = BytesRef.deepCopyOf(term);
    subSources.add(intervalsForTermEnum(this.termPostingBytes, this.termEnum));
    if (++count > maxExpansions) {
      throw new IllegalStateException(
          "Automaton [" + pattern + "] expanded to too many terms (limit " + maxExpansions + ")");
    }
  }
  if (subSources.size() == 0) {
    return null;
  }
  return new DisjunctionIntervalsSource.DisjunctionIntervalIterator(subSources);
}

