float estimateTermPositionsCost(TermsEnum termsEnum) throws IOException {
  this.termOps++;
  this.termEnum = termsEnum;
  int docFreq = this.termEnum.docFreq();
  assert docFreq > 0;
  long totalTermFreq = this.termEnum.totalTermFreq();
  float expOccurrencesInMatchingDoc = totalTermFreq / (float) docFreq;
  if (expOccurrencesInMatchingDoc < 0) {
    expOccurrencesInMatchingDoc = 0;
  }
  this.termPostingCost =
      TERM_POSNS_SEEK_OPS_PER_DOC + expOccurrencesInMatchingDoc * TERM_OPS_PER_POS;
  return this.termPostingCost;
}

